import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Matrix-Sequence-Operator.md","filePath":"manual-en/Matrix-Sequence-Operator.md","lastUpdated":1785684581000}'),d={name:"manual-en/Matrix-Sequence-Operator.md"};function s(o,e,i,p,c,l){return a(),r("div",null,[...e[0]||(e[0]=[n('<h4 id="_16-4-1-2-integer-sequence-operator" tabindex="-1">16.4.1.2 Integer Sequence Operator ‘:’ <a class="header-anchor" href="#_16-4-1-2-integer-sequence-operator" aria-label="Permalink to &quot;16.4.1.2 Integer Sequence Operator ‘:’&quot;">​</a></h4><p>The syntax <code>first:last:step</code> yields a row vector of consecutive integers from first to last counting by step. The final <code>:step</code> is optional and defaults to 1 when omitted.</p><p>Each of first, last, and step must be a scalar and should be an integer (any fractional part is discarded). Because ‘:’ has a high precedence, operands other than numeric literals must usually be parenthesized.</p><p>When step is positive (or omitted) and <em>end &lt; start</em>, or if step is negative and <em>end &gt; start</em>, then the result is an empty matrix. If step is 0, then PSPP reports an error.</p><p>Here are some examples:</p><table tabindex="0"><thead><tr><th>1:6</th><th>⇒</th><th>{1, 2, 3, 4, 5, 6}</th></tr></thead><tbody><tr><td>1:6:2</td><td>⇒</td><td>{1, 3, 5}</td></tr><tr><td>-1:-5:-1</td><td>⇒</td><td>{-1, -2, -3, -4, -5}</td></tr><tr><td>-1:-5</td><td>⇒</td><td>{}</td></tr><tr><td>2:1:0</td><td>⇒</td><td>(error)</td></tr></tbody></table>',6)])])}const m=t(d,[["render",s]]);export{u as __pageData,m as default};
